40	import org.springframework.samples.petclinic.service.ClinicService;
41	import org.springframework.security.access.prepost.PreAuthorize;
42	import org.springframework.web.bind.annotation.CrossOrigin;
43	import org.springframework.web.bind.annotation.RequestMapping;
44	import org.springframework.web.bind.annotation.RestController;
45	import org.springframework.web.util.UriComponentsBuilder;
46	
47	import jakarta.transaction.Transactional;
48	
49	/**
50	 * @author Vitaliy Fedoriv
51	 */
52	
53	@RestController
54	@CrossOrigin(exposedHeaders = "errors, content-type")
55	@RequestMapping("/api")
56	public class OwnerRestControllerV1 implements OwnersApi {
57	
58	    private final ClinicService clinicService;
59	
60	    private final OwnerMapper ownerMapper;
61	
62	    private final PetMapper petMapper;
63	
64	    private final VisitMapper visitMapper;
65	
66	    public OwnerRestControllerV1(ClinicService clinicService,
67	                                 OwnerMapper ownerMapper,
68	                                 PetMapper petMapper,
69	                                 VisitMapper visitMapper) {
70	        this.clinicService = clinicService;
71	        this.ownerMapper = ownerMapper;
72	        this.petMapper = petMapper;
73	        this.visitMapper = visitMapper;
74	    }
75	
76	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
77	    @Override
78	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
79	        Collection<Owner> owners;
80	        if (lastName != null) {
81	            owners = this.clinicService.findOwnerByLastName(lastName);
82	        } else {
83	            owners = this.clinicService.findAllOwners();
84	        }
85	        if (owners.isEmpty()) {
86	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
87	        }
88	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
89	    }
90	
91	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
92	    @Override
93	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
94	        Owner owner = this.clinicService.findOwnerById(ownerId);
95	        if (owner == null) {
96	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
97	        }
98	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
99	    }
100	
101	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
102	    @Override
103	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
104	        validateRequiredFields(ownerFieldsDto);
105	        HttpHeaders headers = new HttpHeaders();
106	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
107	        this.clinicService.saveOwner(owner);
108	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
109	        headers.setLocation(UriComponentsBuilder.newInstance()
110	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
111	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
112	    }
113	
114	    /**
115	     * Rejects an owner whose required fields are missing or blank. Collects the names of every
116	     * offending field so the client learns about all of them at once.
117	     *
118	     * @param ownerFieldsDto the submitted owner fields
119	     * @throws MissingOwnerFieldsException if firstName, lastName, address, city or telephone is
120	     *                                     missing or blank
121	     */
122	    private void validateRequiredFields(OwnerFieldsDto ownerFieldsDto) {
123	        List<String> errors = new ArrayList<>();
124	        if (isBlank(ownerFieldsDto.getFirstName())) {
125	            errors.add("firstName");
126	        }
127	        if (isBlank(ownerFieldsDto.getLastName())) {
128	            errors.add("lastName");
129	        }
130	        if (isBlank(ownerFieldsDto.getAddress())) {
131	            errors.add("address");
132	        }
133	        if (isBlank(ownerFieldsDto.getCity())) {
134	            errors.add("city");
135	        }
136	        if (isBlank(ownerFieldsDto.getTelephone())) {
137	            errors.add("telephone");
138	        }
139	        if (!errors.isEmpty()) {
140	            throw new MissingOwnerFieldsException(errors);
141	        }
142	    }
143	
144	    private boolean isBlank(String value) {
145	        return value == null || value.isBlank();
146	    }
147	
148	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
149	    @Override
150	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
151	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
152	        if (currentOwner == null) {
153	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
154	        }
155	        currentOwner.setAddress(ownerFieldsDto.getAddress());
156	        currentOwner.setCity(ownerFieldsDto.getCity());
157	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
158	        currentOwner.setLastName(ownerFieldsDto.getLastName());
159	        currentOwner.setTelephone(ownerFieldsDto.getTelephone());
160	        this.clinicService.saveOwner(currentOwner);
161	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
162	    }
163	
164	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
165	    @Transactional
166	    @Override
167	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
168	        Owner owner = this.clinicService.findOwnerById(ownerId);
169	        if (owner == null) {
170	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
171	        }
172	        this.clinicService.deleteOwner(owner);
173	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
174	    }
175	
176	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
177	    @Override
178	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
179	        Owner owner = this.clinicService.findOwnerById(ownerId);
180	        if (owner == null) {
181	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
182	        }
183	        HttpHeaders headers = new HttpHeaders();
184	        Pet pet = petMapper.toPet(petFieldsDto);
185	        owner.setId(ownerId);
186	        pet.setOwner(owner);
187	        pet.getType().setName(null);
188	        this.clinicService.savePet(pet);
189	        PetDto petDto = petMapper.toPetDto(pet);
190	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
191	            .buildAndExpand(pet.getId()).toUri());
192	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
193	    }
194	
195	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
196	    @Override
197	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
198	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
199	        if (currentOwner != null) {
200	            Pet currentPet = this.clinicService.findPetById(petId);
201	            if (currentPet != null) {
202	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
203	                currentPet.setName(petFieldsDto.getName());
204	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
205	                this.clinicService.savePet(currentPet);
206	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
207	            }
208	        }
209	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
210	    }
211	
212	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
213	    @Override
214	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
215	        HttpHeaders headers = new HttpHeaders();
216	        Visit visit = visitMapper.toVisit(visitFieldsDto);
217	        Pet pet = new Pet();
218	        pet.setId(petId);
219	        visit.setPet(pet);
220	        this.clinicService.saveVisit(visit);
221	        VisitDto visitDto = visitMapper.toVisitDto(visit);
222	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
223	            .buildAndExpand(visit.getId()).toUri());
224	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
225	    }
226	
227	
228	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
229	    @Override
230	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
231	        Owner owner = this.clinicService.findOwnerById(ownerId);
232	        if (owner != null) {
233	            Pet pet = owner.getPet(petId);
234	            if (pet != null) {
235	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
236	            }
237	        }
238	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
239	    }
240	}
